-              ) : (
-                <span className="text-amber-600">Not connected — publishing will fail for this channel</span>
-              )}
-            </div>
-          </div>
-        )}
-
-        {/* Publish bar */}
-        <div className="mt-4 flex flex-wrap items-center gap-3 border-t border-zinc-100 pt-4">
-          <input
-            type="datetime-local"
-            value={scheduledAt}
