-            disabled={!canSubmit || mutation.isPending}
-            className="rounded-lg border border-zinc-300 px-4 py-1.5 text-sm font-medium hover:bg-zinc-50 disabled:opacity-40"
-          >
-            Save Draft
-          </button>
